	"fmt"
	"strings"
)

func main() {
	var s, stt string
	fmt.Scan(&s)
	fmt.Scan(&stt)

	st := reverse(s)

	sum := 0
	for i := 0; i < len(s); i++ {
		if stt[i] == st[i] {
			sum++
		}
	}

	if sum == len(s) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

func reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

